changeSet.sql:
DECLARE
v_name VARCHAR2(200);
BEGIN
FOR r IN (
SELECT constraint_name
FROM user_constraints
WHERE table_name = 'SENDER_STAGE'
AND constraint_type = 'C'
) LOOP
BEGIN
EXECUTE IMMEDIATE 'ALTER TABLE SENDER_STAGE DROP CONSTRAINT "' || r.constraint_name || '"';
EXCEPTION WHEN OTHERS THEN
NULL;
END;
END LOOP;
END;

